namespace
{
using crd::u16;
using crd::u8;
using crd::usize;
using crd::containers::ConstSpan;
using crd::net::wire::WireError;

namespace schema = crd::net::wire::delta_test;

u8 g_out[crd::fuzz::kMaxInputBytes];

template <typename M>
void exercise(ConstSpan<u8> bytes, u16 writer_minor)
{
    using C = typename M::WireCodec;
    M first{};
    if (crd::net::wire::decode(bytes, writer_minor, first) != WireError::Ok)
    {
        return;
    }
    CRD_FUZZ_REQUIRE(crd::net::wire::same(first, first));
    M second{};
    CRD_FUZZ_REQUIRE(crd::net::wire::decode(bytes, writer_minor, second) == WireError::Ok);
    CRD_FUZZ_REQUIRE(crd::net::wire::same(first, second));
    const bool known = writer_minor <= C::kSchemaMinor;
    if (known)
    {
        CRD_FUZZ_REQUIRE(bytes.size() >= C::kMinBytes);
        CRD_FUZZ_REQUIRE(bytes.size() <= C::kMaxBytes);
    }
    const u16 minor = known ? writer_minor : C::kSchemaMinor;
    usize written = 0U;
    const WireError error = crd::net::wire::encode(first, minor, crd::containers::Span<u8>(g_out), written);
    if (!known && error == WireError::UnknownValue)
    {
        return; // a newer writer's enum value
    }
    CRD_FUZZ_REQUIRE(error == WireError::Ok);
    CRD_FUZZ_REQUIRE(crd::net::wire::encoded_bytes(first, minor) == written);
    if (known)
    {
        CRD_FUZZ_REQUIRE(written == bytes.size());
        CRD_FUZZ_REQUIRE(C::kLossy || written == 0U || std::memcmp(g_out, bytes.data(), written) == 0);
    }
    M again{};
    CRD_FUZZ_REQUIRE(crd::net::wire::decode(ConstSpan<u8>(g_out, written), minor, again) == WireError::Ok);
    CRD_FUZZ_REQUIRE(C::kLossy || crd::net::wire::same(first, again));
}

} // namespace

namespace
{
u8 g_rebuilt[crd::fuzz::kMaxInputBytes + crd::net::wire::kDeltaSlackBytes];
u8 g_delta[crd::fuzz::kMaxInputBytes + crd::net::wire::kDeltaSlackBytes];

template <typename M>
void exercise_delta(const crd::net::wire::DeltaLayout& layout, ConstSpan<u8> bytes, u16 writer_minor)
{
    namespace wire = crd::net::wire;
    if (bytes.size() < 2U)
    {
        return;
    }
    const usize size = (static_cast<usize>(bytes[0]) << 8U) | bytes[1];
    if (size > bytes.size() - 2U)
    {
        return;
    }
    const ConstSpan<u8> baseline = bytes.subspan(2U, size);
    const ConstSpan<u8> rest = bytes.subspan(2U + size);
    M message{};
    if (wire::decode(baseline, writer_minor, message) != WireError::Ok)
    {
        return;
    }
    usize rebuilt = 0U;
    if (wire::delta_apply(layout, baseline, rest, writer_minor, g_rebuilt, rebuilt) == WireError::Ok &&
        wire::decode(ConstSpan<u8>(g_rebuilt, rebuilt), writer_minor, message) == WireError::Ok &&
        writer_minor <= layout.schema_minor)
    {
        usize written = 0U;
        const ConstSpan<u8> whole(g_rebuilt, rebuilt);
        CRD_FUZZ_REQUIRE(wire::delta_encode(layout, baseline, whole, writer_minor, g_delta, written) ==
                         WireError::Ok);
        CRD_FUZZ_REQUIRE(written == rest.size());
        CRD_FUZZ_REQUIRE(written == 0U || std::memcmp(g_delta, rest.data(), written) == 0);
    }
    if (writer_minor > layout.schema_minor ||
        wire::decode(rest, writer_minor, message) != WireError::Ok)
    {
        return;
    }
    usize written = 0U;
    CRD_FUZZ_REQUIRE(wire::delta_encode(layout, baseline, rest, writer_minor, g_delta, written) == WireError::Ok);
    const ConstSpan<u8> delta(g_delta, written);
    CRD_FUZZ_REQUIRE(wire::delta_apply(layout, baseline, delta, writer_minor, g_rebuilt, rebuilt) == WireError::Ok);
    CRD_FUZZ_REQUIRE(rebuilt == rest.size());
    CRD_FUZZ_REQUIRE(rebuilt == 0U || std::memcmp(g_rebuilt, rest.data(), rebuilt) == 0);
}

} // namespace

extern "C" int LLVMFuzzerTestOneInput(const std::uint8_t* data, std::size_t size)
{
    if (size < 2U || size - 2U > crd::fuzz::kMaxInputBytes)
    {
        return 0;
    }
    const ConstSpan<u8> bytes(data + 2U, size - 2U);
    const auto writer_minor = static_cast<u16>(data[1] % (schema::kMinor + 3U));
    switch (data[0] % 7U)
    {
    case 0U:
        exercise<schema::Snapshot>(bytes, writer_minor);
        break;
    case 1U:
        exercise<schema::Roster>(bytes, writer_minor);
        break;
    case 2U:
        exercise<schema::Plain>(bytes, writer_minor);
        break;
    case 3U:
        exercise<schema::Motion>(bytes, writer_minor);
        break;
    case 4U:
        exercise_delta<schema::Snapshot>(schema::kSnapshotLayout, bytes, writer_minor);
        break;
    case 5U:
        exercise_delta<schema::Roster>(schema::kRosterLayout, bytes, writer_minor);
        break;
    case 6U:
        exercise_delta<schema::Motion>(schema::kMotionLayout, bytes, writer_minor);
        break;
    default:
        break;
    }
    return 0;
}

